import type { Vec2 } from './vec.ts';
import { rotate } from './geometry.ts';

/**
 * A greybox building: a rotated rectangle extruded to `height`. Generated by the street pipeline
 * (`streets/buildings.ts`, `CityBuilding` adds its parcel and block); per-district numbers come
 * from `blockout.districts` in world.yaml.
 */
export type Building = {
  center: Vec2;
  width: number;
  depth: number;
  height: number;
  /** Radians, counter-clockwise in the spec plane. */
  angle: number;
  district: string;
};

/** Corners of a building footprint, counter-clockwise starting at (-w/2, -d/2) in local space. */
export function buildingCorners(b: Pick<Building, 'center' | 'width' | 'depth' | 'angle'>): Vec2[] {
  const hw = b.width / 2;
  const hd = b.depth / 2;
  return [
    { x: -hw, y: -hd },
    { x: hw, y: -hd },
    { x: hw, y: hd },
    { x: -hw, y: hd },
  ].map((c) => {
    const r = rotate(c, b.angle);
    return { x: b.center.x + r.x, y: b.center.y + r.y };
  });
}
